var i=`1121-pulled-pork-barbecue`;var t=`world-1121`;var a=`US`;var n=`northern-america`;var s=4;var o=405;var d={en:`Pulled Pork Barbecue`,ua:`Барбекю з рваної свинини`};var u={en:`Pulled Pork Barbecue is a dish from United States prepared with pork shoulder, barbecue sauce, apple cider vinegar, burger bun. This is a home-scale version with measured ingredients in the individual steps where they are used. Oven-braised pulled pork without a barbecue smoker.`,ua:`Барбекю з рваної свинини, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: свиняча лопатка, соус барбекю, яблучний оцет, булочка для бургера. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Рвана свинина тушковано-запечена в духовці без коптильні.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 65 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 65 хвилин.`,t:[`marinating`],m:65,i:[[`pork-shoulder`,1400,`g`],[`smoked-paprika`,12,`g`],[`brown-sugar`,45,`g`],[`table-salt`,15,`g`],[`ground-black-pepper`,8,`g`]]},{en:`Roast the covered pork shoulder at about 135–150°C for 5–6 hours, or until fork-tender and easily shredded; check it is safely cooked.`,ua:`Запікайте лопатку під кришкою при близько 135–150°C протягом 5–6 годин або до м’якості, коли м’ясо легко розділяється виделкою; перевірте повну готовність.`,t:[`slow-roasting`],m:325,i:[]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:12,i:[[`barbecue-sauce`,190,`ml`],[`apple-cider-vinegar`,45,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`burger-bun`,6,`pcs`]]}];var l={slug:i,id:t,country:`US`,region:n,servings:4,minutes:405,title:d,text:u,steps:h};export{a as country,l as default,t as id,o as minutes,n as region,s as servings,i as slug,h as steps,u as text,d as title};